import { readdir } from "node:fs/promises";
import { extname, join, relative, sep } from "node:path";
import { IGNORED_DIRECTORIES } from "./spec.js";

export async function findMarkdownFiles(root: string): Promise<string[]> {
  const files: string[] = [];

  async function visit(directory: string): Promise<void> {
    let entries;
    try {
      entries = await readdir(directory, { withFileTypes: true });
    } catch {
      return;
    }

    for (const entry of entries) {
      const fullPath = join(directory, entry.name);
      if (entry.isDirectory()) {
        if (!IGNORED_DIRECTORIES.has(entry.name)) await visit(fullPath);
        continue;
      }
      if (entry.isFile() && extname(entry.name).toLowerCase() === ".md") {
        files.push(fullPath);
      }
    }
  }

  await visit(root);
  return files.sort((a, b) => a.localeCompare(b));
}

export function toBundlePath(root: string, absolutePath: string): string {
  return relative(root, absolutePath).split(sep).join("/");
}
